WITH kept AS (SELECT s.* FROM accounts s WHERE NOT EXISTS (SELECT 1 FROM transactions x WHERE x.account_id = s.id AND x.txn_time < s.opened_date)) SELECT CASE WHEN balance >= 67000 THEN 'PREMIUM' ELSE 'STANDARD' END AS balance_tier, account_type, COUNT(*) AS num_rows, COUNT(*) FILTER (WHERE status = 'FROZEN') AS frozen_rows, MIN(balance) AS min_balance FROM kept GROUP BY CASE WHEN balance >= 67000 THEN 'PREMIUM' ELSE 'STANDARD' END, account_type ORDER BY frozen_rows DESC
